import {db,fs} from '/tmp/handoff-eleven.mjs';const live=JSON.parse(fs.readFileSync('artifacts/realtor-batch-20261009/live-status.json'));const ev=new Map(live.events.filter(e=>e.event_type==='message.finalized').map(e=>[e.provider_message_id,e]));const affected=live.jobs.filter(j=>ev.get(j.provider_sid?.replace('telnyx:',''))?.status==='delivery_failed'||j.status!=='sent');const out=[];for(const j of affected){const [c]=await db('market_contacts',{id:'eq.'+j.contact_id});const second=(c.notes||'').match(/(?:^|\n)phone2=([^\n]*)/)?.[1]?.trim();const third=(c.notes||'').match(/(?:^|\n)phone3=([^\n]*)/)?.[1]?.trim();out.push({id:c.id,name:c.name,status:j.status,delivery:ev.get(j.provider_sid?.replace('telnyx:',''))?.status,error:j.error||j.last_error,phone2:second||null,phone3:third||null,suppressed:!!(c.do_not_contact||c.cross_channel_suppressed_at)});}fs.writeFileSync('artifacts/realtor-batch-20261009/alternate-number-audit.json',JSON.stringify({at:new Date().toISOString(),rows:out},null,2));console.log(JSON.stringify({affected:out.length,withAlternate:out.filter(x=>x.phone2||x.phone3),withoutAlternate:out.filter(x=>!x.phone2&&!x.phone3).length},null,2));
